def histogram(test):
    # Create an empty dictionary to store letter counts
    count_dict = {}

    # Split the string into words and iterate over them
    for word in test.split():
        if word[0] not in count_dict:
            count_dict[word[0]] = 1
        else:
            count_dict[word[0]] += 1

    # Find the maximum occurrence
    max_count = max(count_dict.values()) if count_dict else 0

    # Create a new dictionary to store letters with maximum occurrence
    result = {k: v for k, v in count_dict.items() if v == max_count}

    return result
```

