def count_nums(arr):
    def get_sum_of_digits(n):
        return sum([int(d) for d in str(n)])

    cnt = 0
    for num in arr:
        if num < 0:
            digits = list(map(int,str(num)[1:]))
            digits[0] *= -1  # convert first digit to negative
            if sum(digits) > 0:
                cnt += 1
        else:
            if get_sum_of_digits(num) > 0:
                cnt += 1
    return cnt
